    "player_id" TEXT NOT NULL,
    "full_name" TEXT NOT NULL,
    "role_code" TEXT,
    "playing_role" TEXT,
    "is_captain" BOOLEAN,
    "is_wicketkeeper" BOOLEAN,
    "batting_style" TEXT,
    "bowling_style" TEXT,
    "date_of_birth" DATE,
    "age_at_tournament" DOUBLE PRECISION,
    "is_overseas" BOOLEAN,
    "is_withdrawn" BOOLEAN,
    "source" TEXT,
    "played_for_team" BOOLEAN,
    "matches_played" BIGINT,
    CONSTRAINT pk_fact_squads PRIMARY KEY ("tournament_id", "team_id", "player_id"),
    CONSTRAINT fk_fact_squads_tournament_id FOREIGN KEY ("tournament_id") REFERENCES analytics.dim_tournaments ("tournament_id"),
    CONSTRAINT fk_fact_squads_player_id FOREIGN KEY ("player_id") REFERENCES analytics.dim_players ("player_id"),
    CONSTRAINT fk_fact_squads_team_id FOREIGN KEY ("team_id") REFERENCES analytics.dim_teams ("team_id"),
    CONSTRAINT ck_fact_squads_matches_nonneg CHECK (matches_played >= 0)
);
COMMENT ON TABLE analytics.fact_squads IS 'fact: one row per player in a team''s tournament squad (with age and whether they played)';
CREATE INDEX IF NOT EXISTS ix_fact_squads_player_id ON analytics.fact_squads ("player_id");
CREATE INDEX IF NOT EXISTS ix_fact_squads_team_id ON analytics.fact_squads ("team_id");
CREATE INDEX IF NOT EXISTS ix_fact_squads_tournament_id_team_id ON analytics.fact_squads ("tournament_id", "team_id");

